103	function fixtureRepo(entries: Tree, version: string): { dir: string; bare: string } {
104	  const dir = temp("update-repo-");
105	  for (const [path, content] of Object.entries(entries)) {
106	    mkdirSync(dirname(join(dir, path)), { recursive: true });
107	    writeFileSync(join(dir, path), content);
108	  }
109	  mkdirSync(dirname(join(dir, RELEASE_MANIFEST)), { recursive: true });
110	  writeFileSync(join(dir, RELEASE_MANIFEST), `${manifestJson(version, Object.keys(entries))}\n`);
111	  // The configuration the machinery reads in a real adopted tree. It is in
112	  // neither release, so the plan must never propose touching it -- a path in
113	  // neither release is invisible to the plan, and this is that property under a
114	  // file the run itself reads through another door.
115	  mkdirSync(dirname(join(dir, ".github/atomaton/config.yaml")), { recursive: true });
116	  writeFileSync(join(dir, ".github/atomaton/config.yaml"), "base_branch: main\ndeploy: {}\n");
117	  gitIn(dir, ["-c", "init.defaultBranch=main", "init"]);
118	  gitIn(dir, ["add", "-A"]);
119	  gitIn(dir, ["-c", "user.name=fixture", "-c", "user.email=fixture@example.test", "commit", "-m", "seed"]);
